# 移除CDN链接的模式
CDN_PATTERNS = [
    r'<link[^>]*fontawesome[^>]*>',
    r'<link[^>]*font-awesome[^>]*>',
    r'<link[^>]*cdnjs\.cloudflare\.com[^>]*>',
    r'<link[^>]*cdn\.jsdelivr\.net[^>]*',
    r'<script[^>]*fontawesome[^>]*>',
    r'<script[^>]*font-awesome[^>]*>',
    r'<!-- FontAwesome CDN removed -->',
]

# 添加SVG图标的样式
SVG_STYLE = '''
<style>
.svg-icon {
    display: inline-block;
    width: 1em;
    height: 1em;
    vertical-align: -0.125em;
    fill: currentColor;
}
</style>
'''

def has_fontawesome(content):
    """检查内容是否包含FontAwesome引用"""
    if any(re.search(pattern, content, re.IGNORECASE) for pattern in CDN_PATTERNS):
        return True
    if re.search(r'fa-[a-z-]+', content):
        return True
    if 'fontawesome' in content.lower():
        return True
    return False

def replace_icon_tags(content):
    """替换FontAwesome图标标签为SVG"""
    # 替换常见的图标
    for icon_class, svg in ICON_SVGS.items():
        # 匹配 <i class="... fa-xxx ..."></i> 格式
        pattern = rf'<i[^>]*class="[^"]*({icon_class})[^"]*"[^>]*></i>'
        content = re.sub(pattern, svg, content, flags=re.IGNORECASE)
        
        # 匹配 <i class='... fa-xxx ...'></i> 格式
        pattern = rf"<i[^>]*class='[^']*({icon_class})[^']*'[^>]*></i>"
        content = re.sub(pattern, svg, content, flags=re.IGNORECASE)
    
    # 处理::before伪元素中使用content: '\fxxx'的情况
    # 这些需要手动处理，这里只移除CDN引用
    
    return content

def remove_cdn_links(content):
    """移除CDN链接"""
    for pattern in CDN_PATTERNS:
        content = re.sub(pattern, '<!-- FontAwesome CDN removed -->', content, flags=re.IGNORECASE)
    return content

def process_file(file_path):
    """处理单个文件"""
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
        
        if not has_fontawesome(content):
            return False
        
        print(f"Detected FontAwesome in: {file_path}")
        original_content = content
        
        # 移除CDN链接
        content = remove_cdn_links(content)
        
        # 替换图标
        content = replace_icon_tags(content)
        
        # 如果内容有变化，写入文件
        if content != original_content:
            # 检查是否需要添加SVG样式
            if '.svg-icon' not in content and '</head>' in content:
                content = content.replace('</head>', SVG_STYLE + '</head>')
            
            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(content)
            return True
        return False
    except Exception as e:
        print(f"Error processing {file_path}: {e}")
        return False

def process_directory(directory):
    """处理目录下的所有HTML文件"""
    processed = 0
    found_files = 0
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith('.html') or file.endswith('.js'):
                found_files += 1
                file_path = os.path.join(root, file)
                if process_file(file_path):
                    print(f"Processed: {file_path}")
                    processed += 1
    print(f"Found {found_files} HTML/JS files in {directory}")
    return processed

if __name__ == '__main__':
    import sys
    
    # 处理多个目录
    directories = [
        os.path.join(os.path.dirname(__file__), 'app/templates'),
        os.path.join(os.path.dirname(__file__), 'templates'),
        os.path.join(os.path.dirname(__file__), 'static'),
        os.path.join(os.path.dirname(__file__), 'ai_engines'),
    ]
    
    total_processed = 0
    for directory in directories:
        if os.path.exists(directory):
            print(f"\nProcessing files in {directory}...")
            count = process_directory(directory)
            total_processed += count
            print(f"Processed {count} files in {directory}")
    
    print(f"\nDone! Total processed {total_processed} files.")
